package com.gympabon.dao;

import java.util.List;

/**
 * Basic CRUD operations shared by every DAO, so each entity only adds the
 * queries that are specific to it.
 *
 * @param <T>  entity type
 * @param <ID> type of the entity identifier
 */
public interface GenericDAO<T, ID> {

    /**
     * Inserts a new entity and sets the identifier generated by the database.
     *
     * @param entity entity to insert
     */
    void save(T entity);

    /**
     * Saves the changes of an existing entity.
     *
     * @param entity entity with its identifier
     */
    void update(T entity);

    /**
     * Finds an entity by its identifier.
     *
     * @param id identifier to look for
     * @return the entity, or null if it does not exist
     */
    T findById(ID id);

    /**
     * Returns every entity of this type.
     *
     * @return the list of entities, empty if there are none
     */
    List<T> findAll();

    /**
     * Deletes an entity by its identifier.
     *
     * @param id identifier of the entity to delete
     */
    void delete(ID id);
}
